    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
for name,sv in [('Demo pair 6',7),('Demo pair 7',1)]:
    gi=G[name+' input']; go=G[name+' output']
    H,W=len(gi),len(gi[0])
    S={(r,c) for r in range(H) for c in range(W) if gi[r][c]==sv}
    A={(r,c) for r in range(H) for c in range(W) if gi[r][c]!=sv and go[r][c]==sv}
    # pairs connected by straight line where every intermediate cell is 0 (or seed at end)
    got=set()
    for (r1,c1) in S:
        for (r2,c2) in S:
            if (r1,c1)<(r2,c2):
                dr,dc=r2-r1,c2-c1
                g=math.gcd(abs(dr),abs(dc))
                if g<2: continue
                dr//=g; dc//=g
                ok=True
                for k in range(1,g):
                    n=(r1+dr*k,c1+dc*k)
                    if gi[n[0]][n[1]]!=0 and n not in S: ok=False;break
                if ok:
                    for k in range(1,g): got.add((r1+dr*k,c1+dc*k))
    print(name,'match:',got==A,'missing',len(A-got),'extra',len(got-A))
    print(sorted(got-A)[:10], sorted(A-got)[:10])

